#include <iostream>
#include <map>
#include <string>
#include <sstream>
using namespace std;

int main() {
    string text = "C++ is great. C++ is powerful. I love C++ programming.";
    map<string, int> wordCount;

    stringstream ss(text);
    string word;

    while (ss >> word) {
        string cleaned = "";
        for (char c : word) {
            if (isalnum(c)) {
                cleaned += tolower(c);
            }
        }
        if (!cleaned.empty()) {
            wordCount[cleaned]++;
        }
    }

    cout << "原文本: " << text << endl;
    cout << "
单词频率:" << endl;

    for (auto& pair : wordCount) {
        cout << pair.first << ": " << pair.second << endl;
    }

    return 0;
}
